import{_ as o,l as r,o as e,c as s,v as t,p as n,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"版图分层与流程","description":"","frontmatter":{"title":"版图分层与流程","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/layout-layers-flow.md","filePath":"litho/layout-layers-flow.md","lastUpdated":1789023840000}'),E={name:"litho/layout-layers-flow.md"};function c(m,a,f,u,A,_){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="版图分层与流程" tabindex="-1">版图分层与流程 <a class="header-anchor" href="#版图分层与流程" aria-label="Permalink to &quot;版图分层与流程&quot;">​</a></h1><div class="epigraph"><p>设计层号不是掩模层：布尔、偏置、派生和填充分完之前，写模机没有一张可曝光的版。</p><footer>—— 对照掩模数据准备中层映射与派生层的产线通称</footer></div><p><a href="/litho/gdsii-oasis">上一课</a>把交换格式钉成带网格的多边形流。缺口是流里有几十上百个层号：哪些进同一张版、哪些只是标注、哪些要先 OR/AND/NOT 才能变成吸收体。本课钉版图分层与派生流程。真正的 MDP 作业链，留给[下一课](/litho/mask-data-prep）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PDK 的 drawing 层、pin、boundary、fill、dummy 与 OPC 输出层不是一一对应扫描机层。一张二元铬版通常对应「某设计层经布尔得到的明暗图」，外加条码、对准标记、 pellicle 区与黑边。EUV 反射版还要派生吸收体开口与多层暴露区，不能把 DUV 透射的极性假设直接贴过去。</p><p>缺口是<strong>层映射表</strong>，不是再解释 GDS 记录。把「metal1 层」当成「metal1 掩模」，会漏掉：辅助图形、缝、槽、化学机械抛光填充是否并入同一张版；双重曝光的分解色是否已经拆成两张。映射错一次，后面 fracturing 写的是另一层工艺。</p><h3 id="极性与色调是流程决定的" tabindex="-1">极性与色调是流程决定的 <a class="header-anchor" href="#极性与色调是流程决定的" aria-label="Permalink to &quot;极性与色调是流程决定的&quot;">​</a></h3><p>正胶/负胶、亮场/暗场、二元/衰减相移，决定布尔之后还要不要 NOT。同一套设计多边形，掩模厂收到的可能是「要镀铬的区域」或「要透光的区域」。合同里的 tone 必须与 <a href="/litho/opc">OPC</a> 模型里的掩模极性一致，否则助条会印反。</p><p><span class="marginnote">fill 与 dummy 常在 TAPOUT 前才插。它们改局部密度，从而改 PEC 与刻蚀负载。层流程若把 fill 排除在 OPC 之外、却写入版，密度核会与签核不一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型顺序：读入设计与 OPC 层 → 按技术文件做布尔派生（sizing、OR 孔与沟、切线合并）→ 插入掩模厂标记与作业框 → 按扫描机层吐出一张张 mask layer。每一步保留层级命名与哈希，以便 die-to-database 知道金标准是派生后还是派生前。</p><p>与 <a href="/litho/six-inch-reticle">6 寸基板</a> 的衔接：有效区、条码、对准键的坐标在这一步就锁进流程，而不是写模时手画。与多重图形衔接：着色后的两张版是两个派生结果，必须成对做套刻标记一致性检查。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>布尔是几何上的集合运算，但对网格多边形会制造零宽度缝、碎片洞和自相交。这些在显示器上看不见，却让 fracturing 产生非法炮或让 MRC 误报。因此派生后要做拓扑清理（并重叠、杀缝），再交给分割。sizing 是掩模偏置的第一种来源——它还不是 <a href="/litho/mpc">MPC</a>，只是把设计意图收成「要写的开口」。</p>',14)),(e(),n(p,null,{default:l(()=>[h(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AE%BE%E8%AE%A1%20%2B%20OPC%20%E5%B1%82%22%5D%20--%3E%20BOOL%5B%22%E5%B8%83%E5%B0%94%20%2F%20sizing%20%2F%20%E6%B4%BE%E7%94%9F%22%5D%0A%20%20BOOL%20--%3E%20MARK%5B%22%E6%A0%87%E8%AE%B0%20%E6%9D%A1%E7%A0%81%20%E9%BB%91%E8%BE%B9%22%5D%0A%20%20MARK%20--%3E%20LAY%5B%22%E6%8C%89%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A%20%20LAY%20--%3E%20MDP%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20MDP%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>层流程不校正电子散射，不代替检验。它只定义「这一张版上有什么多边形」。加密 IP 块若不能在掩模厂展开派生，只能在客户侧完成布尔再交 OASIS.MASK——责任边界要写进 TAPOUT 合同。</p><p>后课默认：掩模层已经是派生后的明暗图；MDP 从这张图开始做分割与校正。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设计层号经布尔与插入标记才成为扫描机层。</li><li>色调、fill 是否入版、分解色拆分，必须与 OPC 模型一致。</li><li>派生会制造缝与自交，清理后再分割。</li><li>出处：掩模数据准备层映射与 PDK 技术文件惯例；SEMI 掩模作业通称。</li></ul>',5))])}const T=o(E,[["render",c]]);export{P as __pageData,T as default};
